import assert from 'node:assert/strict';
import { test } from 'vitest';
import { DEAL_NAME_MAX_LENGTH, isValidDealName } from './deal-name.ts';
import { nameGame, createGame } from './game.ts';
import { EXAMPLE_CODE } from './game.fixture.ts';

test('deal names count UTF-16 code units and keep spaces and other characters', () => {
  assert.equal(DEAL_NAME_MAX_LENGTH, 40);
  assert.equal(isValidDealName('😀'.repeat(20)), true);
  assert.equal(isValidDealName('😀'.repeat(21)), false);
  assert.equal(isValidDealName('  Café / game  '), true);
  assert.equal(isValidDealName(''), true);
  for (const name of ['x'.repeat(41), 'line\nbreak', 'line\rbreak', 'line\r\nbreak', 5])
    assert.equal(isValidDealName(name), false);
});

test('changing a deal name changes only that field and clearing restores unnamed state', () => {
  const game = createGame(EXAMPLE_CODE);
  const named = nameGame(game, '  Café  ');
  assert.deepEqual({ ...named, name: '' }, game);
  assert.equal(named.name, '  Café  ');
  assert.deepEqual(nameGame(named, ''), game);
  for (const name of ['x'.repeat(41), 'x\ny', 'x\ry']) assert.equal(nameGame(game, name), game);
});
import assert from 'node:assert/strict';
import { test } from 'vitest';
import { createGame, nameGame } from './game.ts';
import { EXAMPLE_CODE } from './game.fixture.ts';
import {
  decodeSnapshot,
  encodeSnapshot,
  NAMED_SNAPSHOT_KEYS,
  NAMED_SNAPSHOT_VERSION,
  SNAPSHOT_KEYS,
  SNAPSHOT_VERSION,
} from './snapshot.ts';
import { SelectionKind } from './selection.ts';

function namedSnapshot(overrides: Record<string, unknown> = {}): string {
  return JSON.stringify({
    version: NAMED_SNAPSHOT_VERSION,
    name: 'Café',
    boardCode: EXAMPLE_CODE,
    matched: [],
    selection: { kind: SelectionKind.closed },
    moves: 0,
    elapsedMs: 0,
    started: false,
    ...overrides,
  });
}

test('unnamed and named snapshots use their declared versions and exact fields', () => {
  const unnamed = encodeSnapshot(createGame(EXAMPLE_CODE));
  const named = encodeSnapshot(nameGame(createGame(EXAMPLE_CODE), '  Café  '));
  const unnamedValue: unknown = JSON.parse(unnamed);
  const namedValue: unknown = JSON.parse(named);
  assert.ok(unnamedValue && typeof unnamedValue === 'object');
  assert.ok(namedValue && typeof namedValue === 'object');
  assert.equal(SNAPSHOT_VERSION, 1);
  assert.equal(NAMED_SNAPSHOT_VERSION, 2);
  assert.deepEqual(Object.keys(unnamedValue).sort(), [...SNAPSHOT_KEYS].sort());
  assert.deepEqual(Object.keys(namedValue).sort(), [...NAMED_SNAPSHOT_KEYS].sort());
  assert.deepEqual(decodeSnapshot(unnamed), createGame(EXAMPLE_CODE));
  assert.deepEqual(decodeSnapshot(named), nameGame(createGame(EXAMPLE_CODE), '  Café  '));
});

test('version 2 accepts reordered properties and restores the exact name', () => {
  const text =
    '{"started":true,"selection":{"index":2,"kind":"one"},"name":" Café ",' +
    '"version":2,"elapsedMs":0,"moves":0,"matched":[],"boardCode":"np1-4-1"}';
  const game = decodeSnapshot(text);
  assert.ok(game);
  assert.equal(game.name, ' Café ');
  assert.deepEqual(game.selection, { kind: SelectionKind.one, index: 2 });
});

test('version 2 rejects invalid names and fields while version 1 stays unnamed', () => {
  for (const name of ['', 'x'.repeat(41), 'x\ry', 'x\ny', 5])
    assert.equal(decodeSnapshot(namedSnapshot({ name })), null);
  assert.equal(decodeSnapshot(namedSnapshot({ extra: true })), null);
  const legacy = JSON.stringify({
    version: SNAPSHOT_VERSION,
    boardCode: EXAMPLE_CODE,
    matched: [],
    selection: { kind: SelectionKind.closed },
    moves: 0,
    elapsedMs: 0,
    started: false,
  });
  assert.equal(decodeSnapshot(legacy)?.name, '');
  assert.equal(decodeSnapshot(namedSnapshot({ version: 3 })), null);
});
import { expect, test } from './browser-test.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS } from '../src/game/game.fixture.ts';
import { ReproductionControl } from '../src/game/controls/control-labels.ts';
import { SelectionKind } from '../src/game/selection.ts';
import { exportedSnapshot, loadTimedBoard } from './game-fixture.ts';

const VERSION_ONE = {
  version: 1,
  boardCode: EXAMPLE_CODE,
  matched: [],
  selection: { kind: SelectionKind.one, index: 0 },
  moves: 0,
  elapsedMs: 0,
  started: true,
};

test('deal names export and restore with named snapshots and clear on version 1 imports', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('summary').click();
  const name = page.getByLabel(ReproductionControl.name, { exact: true });
  await expect(name).toHaveValue('');
  await expect(name).toHaveAttribute('maxlength', '40');
  await name.fill('  Café 😊  ');
  await page.locator('summary').click();
  await page.locator('.card').nth(2).click();
  const saved = await exportedSnapshot(page);
  expect(saved).toMatchObject({ version: 2, name: '  Café 😊  ', started: true, moves: 0 });
  expect(saved.selection).toEqual({ kind: SelectionKind.one, index: 2 });

  await page.locator('summary').click();
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  await expect(name).toHaveValue('  Café 😊  ');
  await expect(page.getByRole('button', { name: ReproductionControl.resume, exact: true })).toBeVisible();
  await page.getByRole('button', { name: ReproductionControl.resume, exact: true }).click();

  await page.getByLabel(ReproductionControl.snapshot, { exact: true }).fill(JSON.stringify(VERSION_ONE));
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  await expect(name).toHaveValue('');
  const legacy = await exportedSnapshot(page);
  expect(legacy.version).toBe(1);
  expect(legacy).not.toHaveProperty('name');
});

test('deal names stay out of preferences and clear on replacement while failed loads preserve them', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('summary').click();
  const name = page.getByLabel(ReproductionControl.name, { exact: true });
  await name.fill('Keep this name');
  const boardCode = page.getByLabel(ReproductionControl.board, { exact: true });
  await boardCode.fill('invalid');
  await page.getByRole('button', { name: ReproductionControl.loadBoard, exact: true }).click();
  await expect(name).toHaveValue('Keep this name');
  await expect(page.locator('.load-notice')).toHaveText('Invalid board code.');

  await boardCode.fill(EXAMPLE_CODE);
  await page.getByRole('button', { name: ReproductionControl.loadBoard, exact: true }).click();
  await expect(name).toHaveValue('');
  await name.fill('Clear on restart');
  await page.getByRole('button', { name: 'Restart', exact: true }).click();
  await expect(name).toHaveValue('');
  await name.fill('Clear on size change');
  await page.getByLabel('Grid size', { exact: true }).selectOption('6');
  await expect(name).toHaveValue('');
  await name.fill('Clear on new game');
  await page.getByRole('button', { name: 'New Game', exact: true }).click();
  await expect(name).toHaveValue('');
  await page.reload();
  await page.locator('summary').click();
  await expect(page.getByLabel(ReproductionControl.name, { exact: true })).toHaveValue('');
});

test('completed named snapshots remain static and can be renamed', async ({ page }) => {
  await loadTimedBoard(page);
  await page.locator('summary').click();
  await page.getByLabel(ReproductionControl.snapshot, { exact: true }).fill(
    JSON.stringify({
      version: 2,
      name: 'Finished deal',
      boardCode: EXAMPLE_CODE,
      matched: EXAMPLE_PAIRS.flat(),
      selection: { kind: SelectionKind.closed },
      moves: EXAMPLE_PAIRS.length,
      elapsedMs: 500,
      started: true,
    }),
  );
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  const name = page.getByLabel(ReproductionControl.name, { exact: true });
  await expect(name).toHaveValue('Finished deal');
  await expect(page.getByRole('button', { name: ReproductionControl.resume, exact: true })).toHaveCount(0);
  await expect(page.getByRole('status')).toHaveText('Loaded completed snapshot.');
  await expect(page.locator('.victory.celebrate')).toHaveCount(0);
  await expect(page.locator('.stats dd').nth(3)).toHaveText('none');
  await name.fill('Renamed after the win');
  await page.locator('summary').click();
  expect((await exportedSnapshot(page)).name).toBe('Renamed after the win');
  await expect(page.locator('.victory.celebrate')).toHaveCount(0);
  await expect(page.locator('.stats dd').nth(3)).toHaveText('none');
});

