  const before = await exportedSnapshot(page);

  await page.locator('summary').click();
  const name = page.getByLabel(ReproductionControl.name, { exact: true });
  await name.fill('Live mismatch');
  await expect(name).toBeFocused();
  await page.locator('summary').click();
