import assert from 'node:assert/strict';
import { test } from 'vitest';
import {
  activateCard,
  advanceGame,
  createGame,
  faceUpCards,
  isWon,
  MISMATCH_MS,
  ELAPSED_MAX_MS,
} from './game.ts';
